function customHandler(params) {
  var formData = {};
  for (var i = 0; i < params.length; i++) {
    var p = params[i];
    if (p && typeof p === "object" && typeof p.email === "string" && p.email) {
      formData = p;
      break;
    }
  }
  var email = (formData.email || "").trim();
  var atIndex = email.indexOf("@");
  var name = atIndex > 0 ? email.substring(0, atIndex) : email;
  var image = "https://api.dicebear.com/7.x/initials/svg?seed=" + encodeURIComponent(name);
  return { name: name, image: image };
}

function customHandler(previousContext, params) {
  var selectResult = previousContext;
  var rows = Array.isArray(selectResult) ? selectResult : (selectResult && selectResult.rows ? selectResult.rows : []);
  if (rows.length === 0) { return { isValid: false, email: "" }; }
  var row = rows[0];
  var createdAt = row.created_at ? new Date(row.created_at) : null;
  var now = new Date();
  var thirtyMinutesMs = 30 * 60 * 1000;
  var isExpired = !createdAt || (now.getTime() - createdAt.getTime()) > thirtyMinutesMs;
  var isUsed = row.used === true || row.used === "true";
  var isValid = !isExpired && !isUsed;
  var email = isValid ? (row.email || "") : "";
  return { isValid: isValid, email: email };
}

function customHandler(params) {
  var ctx = params[params.length - 1] || {};
  var current = ctx.current == null ? {} : ctx.current;
  var initial = ctx.initial == null ? {} : ctx.initial;
  var imageDirty = ctx.imageDirty === true || ctx.imageDirty === "true";
  var textDirty = false;
  try {
    textDirty = JSON.stringify(current) !== JSON.stringify(initial);
  } catch (e) {
    textDirty = false;
  }
  return { dirty: textDirty || imageDirty ? "true" : "false" };
}

function customHandler(params) {
  // Walk params to find the data-update-item result row (has id +
  // updatedCount), then the previous currentUser snapshot (no
  // updatedCount, just user fields).
  var updatedRow = null;
  for (var i = 0; i < params.length; i++) {
    var p = params[i];
    if (p && typeof p === "object" && typeof p.id === "string" && p.id.length > 0
        && (p.updatedCount !== undefined || p.email !== undefined || p.name !== undefined)) {
      updatedRow = p;
      break;
    }
  }
  var previous = null;
  for (var j = params.length - 1; j >= 0; j--) {
    var q = params[j];
    if (q && typeof q === "object" && q !== updatedRow
        && (q.id !== undefined || q.email !== undefined)
        && q.updatedCount === undefined && q.fileCount === undefined) {
      previous = q;
      break;
    }
  }
  // state-get-* nodes wrap the value as { value, key }. Unwrap.
  if (previous && previous.value && typeof previous.value === "object"
      && previous.key !== undefined) {
    previous = previous.value;
  }
  if (!updatedRow) {
    return { user: previous || null };
  }
  var merged = Object.assign({}, previous || {}, updatedRow);
  delete merged.password;
  delete merged.password_hash;
  delete merged.updatedCount;
  if (merged.image) {
    var raw = String(merged.image);
    // Strip any prior cache-buster so the URL never grows unbounded.
    raw = raw.replace(/([?&])v=\d+(&|$)/, function(_, lead, tail) {
      if (lead === "?" && tail === "") return "";
      if (lead === "?" && tail === "&") return "?";
      return tail === "&" ? "&" : "";
    });
    if (raw.charAt(raw.length - 1) === "?" || raw.charAt(raw.length - 1) === "&") {
      raw = raw.slice(0, -1);
    }
    var sep = raw.indexOf("?") >= 0 ? "&" : "?";
    merged.image = raw + sep + "v=" + Date.now();
  }
  return { user: merged };
}

