function customHandler(params, inputs, workflowContext) {
  const searchInput = workflowContext[1]?.value || "";
  const statusSelect = workflowContext[2]?.value || "All";
  return {
    keyword: (searchInput || "").trim(),
    status: statusSelect || "All"
  };
}

function customHandler(params, inputs, workflowContext) {
  const formData = params[2] || {};
  const requiredFields = ['name', 'license_number'];
  const missing = requiredFields.filter(field => {
    const value = formData[field];
    return value === null || value === undefined || String(value).trim() === '';
  });
  return { isValid: missing.length === 0, missingFields: missing };
}

function customHandler(params, inputs, workflowContext) {
  const formData = workflowContext[2] || {};
  const requiredFields = ['vehicle_id', 'date_field', 'type_field', 'status_field'];
  const missing = requiredFields.filter(field => {
    const value = formData[field];
    return value === undefined || value === null || value === '';
  });
  return { isValid: missing.length === 0, missing: missing };
}

function customHandler(params, inputs, workflowContext) {
  const formData = workflowContext[2] || {};
  const required = ['vehicle_id', 'driver_id', 'start_time', 'end_time', 'distance_miles'];
  const isValid = required.every(field => {
    const value = formData[field];
    return value !== '' && value !== null && value !== undefined;
  });
  const toNumber = (value) => {
    if (value === '' || value === null || value === undefined) return null;
    const num = Number(value);
    return Number.isNaN(num) ? null : num;
  };
  return {
    isValid: isValid,
    vehicle_id: formData.vehicle_id || null,
    driver_id: formData.driver_id || null,
    start_time: formData.start_time || null,
    end_time: formData.end_time || null,
    distance_miles: toNumber(formData.distance_miles)
  };
}

function customHandler(params, inputs, workflowContext) {
  const spotlight = workflowContext[1]?.value?.[0] || {};
  const recent = workflowContext[4]?.value || [];
  return {
    recentAcknowledgements: [spotlight, ...recent].slice(0, 10),
    criticalSpotlight: []
  };
}

function customHandler(params, inputs, workflowContext) {
  const selectResult = workflowContext[3] || {};
  const report = (selectResult.rows && selectResult.rows[0]) ? selectResult.rows[0] : {};
  if (!report.id) {
    return { csvContent: '', filename: '' };
  }
  const headers = [
    'ID', 'Title', 'Report Date', 'Report Type', 'Primary Metric',
    'Benchmark Badge', 'Interpretation', 'Viz Type', 'Benchmark Context',
    'What Changed', 'Next Step', 'Top Insight', 'Data Sources',
    'Is Featured', 'Image URL', 'Created By User ID'
  ];
  const values = [
    report.id || '',
    report.title || '',
    report.report_date || '',
    report.report_type || '',
    report.primary_metric || '',
    report.benchmark_badge || '',
    report.interpretation || '',
    report.viz_type || '',
    report.benchmark_context || '',
    report.what_changed || '',
    report.next_step || '',
    report.top_insight || '',
    report.data_sources || '',
    report.is_featured ? 'Yes' : 'No',
    report.image_url || '',
    report.created_by_user_id || ''
  ];
  const quoteRegex = new RegExp('"', 'g');
  const spaceRegex = new RegExp('\\s+', 'g');
  const csvContent = headers.map(function(h) {
    return '"' + String(h).replace(quoteRegex, '""') + '"';
  }).join(',') + '\n' +
  values.map(function(v) {
    return '"' + String(v).replace(quoteRegex, '""') + '"';
  }).join(',');
  const dateSuffix = new Date().toISOString().split('T')[0];
  const filename = 'report-' + (report.title ? report.title.replace(spaceRegex, '_').toLowerCase() : report.id) + '-' + dateSuffix + '.csv';
  return { csvContent: csvContent, filename: filename };
}
